import re

_OFFSET = {"WIB": 7, "WITA": 8, "WIT": 9}


def konversi_zona(waktu: str, asal: str, tujuan: str) -> str:
    a = asal.upper()
    t = tujuan.upper()
    if a not in _OFFSET or t not in _OFFSET:
        raise ValueError("zona tidak dikenal")
    m = re.fullmatch(r"([0-9]{2}):([0-9]{2})", waktu)
    if not m:
        raise ValueError("format waktu harus HH:MM")
    jam, menit = int(m.group(1)), int(m.group(2))
    if jam > 23 or menit > 59:
        raise ValueError("jam atau menit di luar rentang")
    total = jam * 60 + menit + (_OFFSET[t] - _OFFSET[a]) * 60
    hari, sisa = divmod(total, 24 * 60)
    hasil = f"{sisa // 60:02d}:{sisa % 60:02d}"
    if hari > 0:
        hasil += " (+1 hari)"
    elif hari < 0:
        hasil += " (-1 hari)"
    return hasil

