from decimal import Decimal, ROUND_HALF_UP

_BOBOT = {
    "A": Decimal("4.00"), "AB": Decimal("3.50"), "B": Decimal("3.00"),
    "BC": Decimal("2.50"), "C": Decimal("2.00"), "D": Decimal("1.00"),
    "E": Decimal("0.00"),
}


def hitung_ipk(nilai: list) -> float:
    terbaik = {}
    for kode, sks, huruf in nilai:
        if huruf not in _BOBOT:
            raise ValueError(f"huruf mutu tidak dikenal: {huruf!r}")
        if not isinstance(sks, int) or sks <= 0:
            raise ValueError("sks harus bilangan bulat positif")
        bobot = _BOBOT[huruf]
        if kode not in terbaik or bobot > terbaik[kode][1]:
            terbaik[kode] = (sks, bobot)
    if not terbaik:
        return 0.0
    total_sks = sum(s for s, _ in terbaik.values())
    total_mutu = sum(s * b for s, b in terbaik.values())
    ipk = (total_mutu / total_sks).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return float(ipk)

