from fractions import Fraction


def upah_lembur(upah_bulanan: int, jam: int, hari_libur: bool) -> int:
    if upah_bulanan < 0 or jam < 0:
        raise ValueError("nilai tidak boleh negatif")
    pengali = Fraction(0)
    for ke in range(1, jam + 1):
        if hari_libur:
            if ke <= 8:
                pengali += 2
            elif ke == 9:
                pengali += 3
            else:
                pengali += 4
        else:
            pengali += Fraction(3, 2) if ke == 1 else 2
    total = Fraction(upah_bulanan) * pengali / 173
    return int(total + Fraction(1, 2))

