from fractions import Fraction


def bagi_kursi(suara: dict, jumlah_kursi: int, ambang_persen: int) -> dict:
    if jumlah_kursi < 0:
        raise ValueError("jumlah kursi tidak boleh negatif")
    if any(v < 0 for v in suara.values()):
        raise ValueError("suara tidak boleh negatif")
    hasil = {p: 0 for p in suara}
    if jumlah_kursi == 0:
        return hasil
    total = sum(suara.values())
    if total == 0:
        raise ValueError("total suara 0")
    lolos = [p for p, v in suara.items() if v * 100 >= ambang_persen * total]
    if not lolos:
        raise ValueError("tidak ada partai yang lolos ambang batas")
    for _ in range(jumlah_kursi):
        pemenang = min(
            lolos,
            key=lambda p: (-Fraction(suara[p], 2 * hasil[p] + 1), -suara[p], p),
        )
        hasil[pemenang] += 1
    return hasil

