from datetime import datetime


def _biaya_sisa(menit: int) -> int:
    if menit == 0:
        return 0
    if menit <= 120:
        return 5000
    tambahan_jam = -(-(menit - 120) // 60)
    return min(5000 + 3000 * tambahan_jam, 25000)


