    t_masuk = datetime.strptime(masuk, "%Y-%m-%d %H:%M")
    t_keluar = datetime.strptime(keluar, "%Y-%m-%d %H:%M")
    if t_keluar < t_masuk:
        raise ValueError("waktu keluar sebelum waktu masuk")
    durasi = int((t_keluar - t_masuk).total_seconds()) // 60
    if durasi <= 15:
        return 0
    hari, sisa = divmod(durasi, 1440)
    return hari * 25000 + _biaya_sisa(sisa)

