from collections import deque


def langkah_terpendek(peta: list) -> int:
    if not peta:
        raise ValueError("peta kosong")
    lebar = len(peta[0])
    if any(len(baris) != lebar for baris in peta):
        raise ValueError("panjang baris tidak sama")
    awal, akhir = [], []
    for r, baris in enumerate(peta):
        for c, ch in enumerate(baris):
            if ch not in ".#SE":
                raise ValueError(f"karakter tidak dikenal: {ch!r}")
            if ch == "S":
                awal.append((r, c))
            elif ch == "E":
                akhir.append((r, c))
    if len(awal) != 1 or len(akhir) != 1:
        raise ValueError("harus ada tepat satu S dan satu E")
    tinggi = len(peta)
    mulai, tujuan = awal[0], akhir[0]
    jarak = {mulai: 0}
    antrian = deque([mulai])
    while antrian:
        r, c = antrian.popleft()
        if (r, c) == tujuan:
            return jarak[(r, c)]
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < tinggi and 0 <= nc < lebar and peta[nr][nc] != "#" and (nr, nc) not in jarak:
                jarak[(nr, nc)] = jarak[(r, c)] + 1
                antrian.append((nr, nc))
    return -1

