import re

_LABEL = {"alpha": 0, "beta": 1, "rc": 2, None: 3}
_POLA = re.compile(r"([0-9]+(?:\.[0-9]+)*)(?:-(alpha|beta|rc))?")


def bandingkan_versi(a: str, b: str) -> int:
    ma, mb = _POLA.fullmatch(a), _POLA.fullmatch(b)
    if not ma or not mb:
        raise ValueError("format versi tidak valid")
    bagian_a = ma.group(1).split(".")
    bagian_b = mb.group(1).split(".")
    n = max(len(bagian_a), len(bagian_b))
    bagian_a += ["0"] * (n - len(bagian_a))
    bagian_b += ["0"] * (n - len(bagian_b))
    kunci_a = (bagian_a, _LABEL[ma.group(2)])
    kunci_b = (bagian_b, _LABEL[mb.group(2)])
    return (kunci_a > kunci_b) - (kunci_a < kunci_b)
