def susun_semester(prasyarat: dict, maks_per_semester: int) -> list:
    if maks_per_semester < 1:
        raise ValueError("maks_per_semester minimal 1")
    semua = set(prasyarat)
    for daftar in prasyarat.values():
        semua.update(daftar)
    syarat = {mk: set(prasyarat.get(mk, [])) for mk in semua}
    selesai = set()
    rencana = []
    while len(selesai) < len(semua):
        siap = sorted(mk for mk in semua - selesai if syarat[mk] <= selesai)
        if not siap:
            raise ValueError("ada ketergantungan melingkar")
        ambil = siap[:maks_per_semester]
        rencana.append(ambil)
        selesai.update(ambil)
    return rencana

