def hitung(ekspresi: str) -> int:
    token = []
    i = 0
    while i < len(ekspresi):
        ch = ekspresi[i]
        if ch == " ":
            i += 1
        elif ch in "0123456789":
            j = i
            while j < len(ekspresi) and ekspresi[j] in "0123456789":
                j += 1
            token.append(int(ekspresi[i:j]))
            i = j
        elif ch in "+-*/()":
            token.append(ch)
            i += 1
        else:
            raise ValueError(f"karakter tidak valid: {ch!r}")

    pos = 0

    def lihat():
        return token[pos] if pos < len(token) else None

    def ambil():
        nonlocal pos
        t = token[pos]
        pos += 1
        return t

    def ekspr():
        nilai = suku()
        while lihat() in ("+", "-"):
            op = ambil()
            kanan = suku()
            nilai = nilai + kanan if op == "+" else nilai - kanan
        return nilai

    def suku():
        nilai = faktor()
        while lihat() in ("*", "/"):
            op = ambil()
            kanan = faktor()
            if op == "*":
                nilai = nilai * kanan
            else:
                if kanan == 0:
                    raise ZeroDivisionError("pembagian dengan nol")
                q = abs(nilai) // abs(kanan)
                nilai = q if (nilai >= 0) == (kanan > 0) else -q
        return nilai

    def faktor():
        t = lihat()
        if t == "-":
            ambil()
            return -faktor()
        if t == "(":
            ambil()
            nilai = ekspr()
            if lihat() != ")":
                raise ValueError("kurung tidak seimbang")
            ambil()
            return nilai
        if isinstance(t, int):
            ambil()
            return t
        raise ValueError("ekspresi tidak valid")

    hasil = ekspr()
    if pos != len(token):
        raise ValueError("ada token sisa")
    return hasil

